from pathlib import Path
import json,shutil
B=Path(__file__).resolve().parent;D=json.loads((B/'研究与产品数据.json').read_text());O=B/'deliverables'
page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>高端单身旅行与线下社群研究</title><style>
:root{--ink:#203841;--gold:#98733c;--paper:#f6f3ed;--line:#d9dedb}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.75 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}header{padding:48px max(5vw,24px) 35px;background:#203841;color:white}header small{color:#d6bc91;letter-spacing:3px}h1{font:500 clamp(28px,4vw,48px)/1.4 "Songti SC",serif;margin:18px 0}h2{font-size:26px;margin:0 0 18px}h3{font-size:20px;margin:0 0 12px}p{margin:10px 0}nav{position:sticky;top:0;z-index:5;display:flex;gap:10px;flex-wrap:wrap;padding:12px 5vw;background:#f6f3edf5;border-bottom:1px solid var(--line)}button,a.button{font:inherit;cursor:pointer;border:1px solid #aebdbb;background:transparent;padding:8px 16px;border-radius:3px;color:inherit;text-decoration:none}button.active{background:var(--ink);color:white}main{max-width:1320px;margin:0 auto;padding:32px 5vw}section{display:none}section.active{display:block}.lead{font-size:19px;max-width:1000px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:28px 0}.card{padding:24px;background:white;border:1px solid var(--line)}.num{font-size:32px;font-family:Georgia;color:var(--gold)}.note{font-size:14px;color:#5b6a6c}details{background:white;border-top:1px solid var(--line);padding:20px 24px;margin:12px 0}summary{cursor:pointer;font-size:20px;font-weight:600}summary small{font-size:13px;color:#687774;margin-left:14px}.field{display:grid;grid-template-columns:125px 1fr;border-top:1px solid #e8eae6;padding:11px 0}.field b{font-weight:600}a{color:#6f5129;text-underline-offset:4px}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.inputs{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}label{display:block;font-size:14px}input,select{display:block;font:inherit;width:100%;margin-top:5px;padding:9px;border:1px solid #aab8b8;background:white;border-radius:2px}.bar{display:grid;grid-template-columns:90px 1fr 110px;gap:14px;align-items:center;margin:18px 0}.track{background:#e3e7e6;height:20px}.fill{background:#305969;height:20px;min-width:2px}.scroll{overflow:auto}table{border-collapse:collapse;min-width:650px;width:100%;background:white;margin:22px 0}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#e5eae8}.downloads{display:flex;gap:14px;flex-wrap:wrap}.source{font-size:14px;margin-top:15px}footer{margin-top:50px;border-top:1px solid var(--line);padding:24px 0}.badge{font-size:12px;color:#746043} @media(max-width:760px){.grid,.inputs{grid-template-columns:1fr}.field{grid-template-columns:1fr}.field b{margin-bottom:5px}nav{position:static}main{padding:25px 20px}.bar{grid-template-columns:65px 1fr 85px}header{padding:30px 20px}summary small{display:block;margin-left:0}}
</style></head><body><header><small>GATSBY CLUB  RESEARCH</small><h1>高端单身旅行与线下社群研究</h1><p>北京先相识，三亚再同行。商务学习线独立验证持续参加。</p><p class="note" style="color:#d7dfdc">2026年10月23日 · 私有研究初案 · 试价与成本尚待询价和客户反馈</p></header><nav id="nav"><button class="active" data-tab="overview">决策概要</button><button data-tab="cases">国内对标</button><button data-tab="foreign">国外九家</button><button data-tab="products">首发产品</button><button data-tab="model">收费测算</button><button data-tab="evidence">来源与下一步</button></nav><main>
<section id="overview" class="active"><h2>先验证三件事</h2><p class="lead">合适的人是否愿意为同一场活动付费；线下相识能否带来旅行购买；旅行试价能否覆盖有质量的交付。BoL／BoL Selected已确认，当前无已确认交付资源。</p><div class="grid" id="overviewCards"></div><h3>本次建议</h3><p>先做单身晚宴。三亚保留一条四天三晚初案，北京周边作为同口径比较研究。商务分享会先找有真实案例的讲师和可控制成本的场地。</p><div class="scroll"><table><thead><tr><th>会议选择</th><th>建议</th><th>需要的证据</th></tr></thead><tbody><tr><td>谁先参加</td><td>北京30至42岁真实单身者；资产口径另议</td><td>过往消费、可出行时间及同行偏好</td></tr><tr><td>卖什么</td><td>晚宴、商务分享、三亚四天三晚独住小团</td><td>两场活动结构与承办报价</td></tr><tr><td>投多少</td><td>分阶段投入，旅行基准周转金约7.52万元</td><td>定金尾款、退款和供应商付款条件</td></tr></tbody></table></div><div class="downloads"><a class="button" href="高端单身旅行与线下社群研究报告.pdf">正式报告 PDF</a><a class="button" href="高端单身旅行与线下社群研究数据.xlsx">Excel 数据与模型</a><a class="button" href="历史国外案例网站.html">既有案例与图像档案</a></div><p class="note">历史网站为2026年10月19日前轮方案，旧价格与模型仅作历史记录；当前口径以本页和本轮文件为准。</p></section>
<section id="cases"><h2>国内对标</h2><p>六个重点对象分别解决旅行交付、婚恋筛选、双线活动与内容获客。补充产品提供价格和流程参照，尚无六家同等完整的旅行经营实绩。</p><div class="filters" id="filters"></div><div id="caseList"></div></section>
<section id="foreign"><h2>国外九家可以借鉴什么</h2><p>保留具体收费与组织方式，先复制活动，不承担同等会所资产。</p><div id="foreignList"></div></section>
<section id="products"><h2>两场活动与一条旅行</h2><div id="productList"></div></section>
<section id="model"><h2>价格、人数与现金需要</h2><p>规划测算。默认展示基准人数。修改输入即可查看变化，刷新恢复原始值。</p><div class="card"><label>选择产品<select id="productSelect"></select></label><div class="inputs" id="modelInputs"></div><div id="modelResults"></div><div id="scenarioBars"></div><p class="note">贡献已含项目工时与获客成本，未扣公司日常开支和税费。退款按全部交付成本已发生演示。财务保本人数与社交成团条件分别判断。</p></div></section>
<section id="evidence"><h2>公开事实与待补证据</h2><p>本轮复核机构官网、旅行商品、招募和会员规则；平台声量复用10月22日快照。本轮没有新抓一套90天平台内容。客户访谈与供应商咨询由合伙人推进。</p><div id="gapList"></div><h3>来源入口</h3><div id="sources"></div></section>
<footer>本轮新增资料仅在本地保存，未发布至公开GitHub。<br>所有试价均供内部研究讨论。</footer></main><script>const DATA=__DATA__;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),rmb=n=>'¥'+Math.round(n).toLocaleString('zh-CN');
const sources=Object.fromEntries(DATA.sources.map(s=>[s.id,s]));
const refs=ids=>'<div class="source">'+ids.map(id=>sources[id].url?`<a href="${esc(sources[id].url)}" target="_blank" rel="noopener">${id} ${esc(sources[id].name)}</a>`:`${id} 用户私有资料`).join('　')+'</div>';
const field=(n,v)=>`<div class="field"><b>${esc(n)}</b><div>${esc(v)}</div></div>`;
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('section,nav button').forEach(e=>e.classList.remove('active'));$('#'+b.dataset.tab).classList.add('active');b.classList.add('active');window.scrollTo({top:0,behavior:'smooth'});});
$('#overviewCards').innerHTML=DATA.products.map(p=>`<div class="card"><h3>${esc(p.name)}</h3><div class="num">${rmb(p.price)}<small style="font-size:14px">／人</small></div><p>基准${p.base}人，上限${p.capacity}人</p><p class="note">研究试价，尚无客户付费证明</p></div>`).join('');
const groups=['全部','旅行社主导','婚恋机构主导','独立社群主导','独立平台线索'];
function showCases(group='全部'){$('#caseList').innerHTML=DATA.cases.filter(c=>group==='全部'||c.group===group||group==='独立社群主导'&&c.group.includes('主理')).map(c=>`<details><summary>${esc(c.name)}<small>${esc(c.product)}　${esc(c.status)}</small></summary>${field('客户与准入',c.customer)}${field('怎样收费',c.price)}${field('包含什么',c.rights)}${field('组织流程',c.flow)}${field('怎样获客',c.acquisition)}${field('经营表现',c.performance)}${field('我们的判断',c.judgment)}${refs(c.sources)}</details>`).join('');}
$('#filters').innerHTML=groups.map((g,i)=>`<button ${i?'':'class="active"'} data-group="${g}">${g}</button>`).join('');document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-group]').forEach(e=>e.classList.remove('active'));b.classList.add('active');showCases(b.dataset.group);});showCases();
$('#foreignList').innerHTML=DATA.foreign.map(c=>`<details><summary>${esc(c.name)}</summary><p>${esc(c.what)}</p>${field('收费权益',c.fees)}${field('组织入口',c.activity)}${field('借鉴判断',c.judgment)}${refs(c.sources)}</details>`).join('');
$('#productList').innerHTML=DATA.products.map(c=>`<details open><summary>${esc(c.name)}<small>试价${rmb(c.price)}／人</small></summary>${field('谁参加',c.customer)}${field('为何付款',c.reason)}${field('包含与另付',c.rights)}<ol>${c.flow.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>${field('团队',c.team)}${field('后续参加',c.retention)}</details>`).join('');
$('#gapList').innerHTML=DATA.gaps.map(g=>`<details><summary>${esc(g[0])}<small>${esc(g[3])}</small></summary><p>${esc(g[1])}</p><p>${esc(g[4])}</p><p class="note">负责人 ${esc(g[2])}</p></details>`).join('');
$('#sources').innerHTML=DATA.sources.map(s=>`<p class="source">${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener">${s.id} ${esc(s.name)}</a>`:`${s.id} ${esc(s.name)}`}<br>${esc(s.kind)}；${esc(s.period)}。${esc(s.note)}</p>`).join('');
$('#productSelect').innerHTML=DATA.products.map((p,i)=>`<option value="${i}">${esc(p.name)}</option>`).join('');
const controls=[['price','售价 元'],['n','付费人数'],['v','单人交付 元'],['cac','单人获客 元'],['fixed','固定与工时 元'],['refund','退款金额占比 %']];
function setProduct(){let p=DATA.products[Number($('#productSelect').value)],vals={price:p.price,n:p.base,v:p.var,cac:p.cac,fixed:p.fixed,refund:3};$('#modelInputs').innerHTML=controls.map(([id,label])=>`<label>${label}<input type="number" id="input-${id}" value="${vals[id]}" min="0" ${id==='n'?`max="${p.capacity}" step="1"`:'step="any"'} ${id==='refund'?'max="100"':''}></label>`).join('');document.querySelectorAll('#modelInputs input').forEach(e=>e.oninput=calculate);calculate();}
function calculate(){let a={};for(const[id]of controls){let el=$('#input-'+id);if(el.value===''||!el.checkValidity()){$('#modelResults').textContent='请填写范围内的完整数值。';$('#scenarioBars').innerHTML='';return;}a[id]=Number(el.value);}if(!Number.isInteger(a.n)){$('#modelResults').textContent='人数需为整数。';return;}const gross=a.price*a.n,refund=gross*a.refund/100,revenue=gross-refund,total=a.n*(a.v+a.cac)+a.fixed,profit=revenue-total,be=a.price*(1-a.refund/100)-a.v-a.cac,early=a.fixed*.4+a.n*a.cac,after=gross*.3-a.n*a.v*.7-a.fixed-a.n*a.cac,cash=Math.max(early,-after,0)+refund;
$('#modelResults').innerHTML=`<div class="grid"><div><p>扣退款后收入</p><div class="num">${rmb(revenue)}</div></div><div><p>单次贡献</p><div class="num" id="contribution">${rmb(profit)}</div></div><div><p>启动周转金</p><div class="num" id="cash">${rmb(cash)}</div></div></div><p>财务保本：${be>0?Math.ceil(a.fixed/be)+'人':'当前售价无保本人数'}。旅行建议至少12人，并满足同行结构条件。</p>`;
const p=DATA.products[Number($('#productSelect').value)],vals=[p.low,p.base,p.full].map(n=>({n,v:a.price*n*(1-a.refund/100)-n*(a.v+a.cac)-a.fixed})),max=Math.max(...vals.map(x=>Math.abs(x.v)),1);
$('#scenarioBars').innerHTML='<h3>低于预期、基准、满团人数下的贡献</h3>'+vals.map(x=>`<div class="bar"><span>${x.n}人</span><div class="track"><div class="fill" style="width:${Math.abs(x.v)/max*100}%;background:${x.v<0?'#a15c4f':'#305969'}"></div></div><strong>${rmb(x.v)}</strong></div>`).join('');}
$('#productSelect').onchange=setProduct;setProduct();
</script></body></html>'''
page=page.replace('__DATA__',json.dumps(D,ensure_ascii=False).replace('</','<\\/'))
(O/'研究讨论网站.html').write_text(page)
(B/'site/index.html').write_text(page)
shutil.copy2(B.parent.parent/'.research-private/github-export/GatsbyClub/private-club-site/dist/index.html',O/'历史国外案例网站.html')
print('local website built')
